import Foundation
import NIOCore
import NIOHTTP1

/// Static shell for the phone/web agent UI, embedded in the binary so every
/// `krill serve` ships it with no packaging step (no resource bundle to lose
/// in `make dist`). Three files: the app page, the PWA manifest, the icon.
/// The shell is served unauthenticated (it contains no data); the page asks
/// for the API key and sends it as a Bearer token on every API call.
///
/// The page source is maintained INLINE below as a Swift raw string. It is a
/// single self-contained file (no external assets), so editing it is editing
/// the string; keep it dependency-free and same-origin.
extension HTTPHandler {
    func handleWebUI(context: ChannelHandlerContext, method: HTTPMethod, path: String) {
        guard method == .GET || method == .HEAD else {
            return sendJSON(context: context, status: .methodNotAllowed,
                            body: ["error": "method not allowed"])
        }
        switch path {
        case "/ui", "/ui/":
            sendStatic(context: context, contentType: "text/html; charset=utf-8",
                       data: Data(WebUI.indexHTML.utf8))
        case "/ui/manifest.webmanifest":
            sendStatic(context: context, contentType: "application/manifest+json",
                       data: Data(WebUI.manifest.utf8))
        case "/ui/icon.png":
            sendStatic(context: context, contentType: "image/png", data: WebUI.iconPNG,
                       cacheControl: "public, max-age=86400")
        default:
            sendJSON(context: context, status: .notFound, body: ["error": "Not found: \(path)"])
        }
    }

    private func sendStatic(
        context: ChannelHandlerContext, contentType: String, data: Data,
        cacheControl: String = "no-cache"
    ) {
        var headers = HTTPHeaders()
        headers.add(name: "Content-Type", value: contentType)
        headers.add(name: "Content-Length", value: "\(data.count)")
        headers.add(name: "Cache-Control", value: cacheControl)
        let head = HTTPResponseHead(version: .http1_1, status: .ok, headers: headers)
        context.write(wrapOutboundOut(.head(head)), promise: nil)
        var buf = ByteBufferAllocator().buffer(capacity: data.count)
        buf.writeBytes(data)
        context.write(wrapOutboundOut(.body(.byteBuffer(buf))), promise: nil)
        context.writeAndFlush(wrapOutboundOut(.end(nil)), promise: nil)
    }
}

enum WebUI {
    static let manifest = #"""
    {
      "name": "Krill",
      "short_name": "Krill",
      "start_url": "/ui",
      "scope": "/ui",
      "display": "standalone",
      "background_color": "#0b0f14",
      "theme_color": "#0b0f14",
      "icons": [{ "src": "/ui/icon.png", "sizes": "256x256", "type": "image/png" }]
    }
    """#

    /// 256x256 app icon (coral K on deep ocean; regenerate with an AppKit
    /// script if the brand mark changes).
    static let iconPNG: Data = Data(base64Encoded: iconBase64) ?? Data()
    private static let iconBase64 = ""

    static let indexHTML = #"""
<!doctype html>
<html lang="en">
<head>
<meta charset="utf-8">
<meta name="viewport" content="width=device-width, initial-scale=1, viewport-fit=cover, interactive-widget=resizes-content">
<meta name="apple-mobile-web-app-capable" content="yes">
<meta name="mobile-web-app-capable" content="yes">
<meta name="apple-mobile-web-app-status-bar-style" content="black-translucent">
<meta name="apple-mobile-web-app-title" content="Krill">
<meta name="theme-color" content="#0b0f14">
<link rel="manifest" href="/ui/manifest.webmanifest">
<link rel="apple-touch-icon" href="/ui/icon.png">
<link rel="icon" href="/ui/icon.png">
<title>Krill</title>
<style>
:root {
  --bg: #0b0f14; --surface: #121a26; --surface2: #1a2434; --raise: #202c40;
  --line: rgba(255,255,255,.08); --line2: rgba(255,255,255,.14);
  --text: #e8edf4; --dim: #8b96a8; --faint: #5b6678;
  --accent: #ff7365; --accent-soft: rgba(255,115,101,.14);
  --ok: #34d399; --warn: #fbbf24; --err: #f87171; --user: #223350;
  --mono: ui-monospace, "SF Mono", SFMono-Regular, Menlo, monospace;
  --sans: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, sans-serif;
  --sat: env(safe-area-inset-top, 0px); --sab: env(safe-area-inset-bottom, 0px);
}
* { box-sizing: border-box; -webkit-tap-highlight-color: transparent; }
html, body { height: 100%; }
body {
  margin: 0; background: var(--bg); color: var(--text);
  font: 16px/1.5 var(--sans); overscroll-behavior: none;
  -webkit-font-smoothing: antialiased; text-size-adjust: 100%;
}
button { font: inherit; color: inherit; background: none; border: 0; cursor: pointer; }
input, textarea, select { font: inherit; color: var(--text); }
::selection { background: rgba(255,115,101,.35); }

#app { height: 100dvh; display: flex; flex-direction: column; }
.view { flex: 1; min-height: 0; display: none; flex-direction: column; }
.view.active { display: flex; }

/* ---------- header ---------- */
.hdr {
  display: flex; align-items: center; gap: 10px;
  padding: calc(10px + var(--sat)) 16px 10px;
  background: rgba(11,15,20,.82); backdrop-filter: blur(18px);
  -webkit-backdrop-filter: blur(18px);
  border-bottom: 1px solid var(--line); flex: none; z-index: 5;
}
.hdr h1 { font-size: 19px; font-weight: 700; margin: 0; letter-spacing: .2px; }
.orb {
  width: 10px; height: 10px; border-radius: 50%; background: var(--faint); flex: none;
  transition: background .3s, box-shadow .3s;
}
.orb.ready { background: var(--ok); box-shadow: 0 0 10px rgba(52,211,153,.7); animation: pulse 2.6s ease-in-out infinite; }
.orb.idle  { background: var(--warn); }
.orb.down  { background: var(--err); }
@keyframes pulse { 50% { box-shadow: 0 0 3px rgba(52,211,153,.25); } }
.hdr .chip {
  font-size: 12px; color: var(--dim); background: var(--surface2);
  border: 1px solid var(--line); padding: 3px 10px; border-radius: 99px;
  max-width: 45vw; overflow: hidden; text-overflow: ellipsis; white-space: nowrap;
}
.spacer { flex: 1; }
.iconbtn {
  width: 38px; height: 38px; border-radius: 12px; display: grid; place-items: center;
  color: var(--dim); font-size: 19px; flex: none;
}
.iconbtn:active { background: var(--surface2); }

/* ---------- sessions list ---------- */
.scroll { flex: 1; min-height: 0; overflow-y: auto; -webkit-overflow-scrolling: touch; }
.slist { padding: 14px 14px calc(96px + var(--sab)); display: flex; flex-direction: column; gap: 10px; }
.scard {
  background: var(--surface); border: 1px solid var(--line); border-radius: 16px;
  padding: 14px 16px; text-align: left; width: 100%; display: block;
}
.scard:active { background: var(--surface2); }
.scard .t { font-weight: 600; font-size: 15px; margin-bottom: 5px; display: flex; gap: 8px; align-items: center; min-width: 0; }
.scard .t span.txt { overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
.scard .m { font-size: 12.5px; color: var(--dim); display: flex; gap: 6px; align-items: center; }
.pill {
  font-size: 11px; font-weight: 600; padding: 2px 9px; border-radius: 99px; flex: none;
  letter-spacing: .3px; text-transform: uppercase;
}
.pill.idle { background: rgba(139,150,168,.15); color: var(--dim); }
.pill.running { background: rgba(52,211,153,.14); color: var(--ok); }
.pill.waiting { background: rgba(251,191,36,.15); color: var(--warn); }
.pill.cancelled { background: rgba(248,113,113,.13); color: var(--err); }
.empty { text-align: center; color: var(--dim); padding: 70px 30px; }
.empty .big { font-size: 40px; margin-bottom: 12px; }
.fab {
  position: absolute; right: 20px; bottom: calc(24px + var(--sab));
  width: 58px; height: 58px; border-radius: 20px; background: var(--accent);
  color: #14100f; font-size: 30px; font-weight: 400; display: grid; place-items: center;
  box-shadow: 0 8px 28px rgba(255,115,101,.42); z-index: 6;
}
.fab:active { transform: scale(.94); }

/* ---------- session view ---------- */
.transcript { padding: 16px 14px 10px; display: flex; flex-direction: column; gap: 12px; }
.msg { max-width: 88%; }
.msg.user { align-self: flex-end; background: var(--user); border-radius: 18px 18px 5px 18px; padding: 10px 15px; white-space: pre-wrap; overflow-wrap: break-word; }
.msg.assistant { align-self: stretch; max-width: 100%; overflow-wrap: break-word; }
.msg.assistant .md > :first-child { margin-top: 0; }
.msg.assistant .md > :last-child { margin-bottom: 0; }
.md p { margin: .55em 0; }
.md h1, .md h2, .md h3 { font-size: 1.06em; margin: .8em 0 .35em; }
.md ul, .md ol { margin: .4em 0; padding-left: 1.4em; }
.md code { font-family: var(--mono); font-size: .86em; background: var(--surface2); border: 1px solid var(--line); padding: 1px 5px; border-radius: 6px; }
.md pre { background: var(--surface); border: 1px solid var(--line); border-radius: 12px; padding: 11px 13px; overflow-x: auto; }
.md pre code { background: none; border: 0; padding: 0; font-size: 12.5px; line-height: 1.55; }
.md a { color: var(--accent); }
.note { align-self: center; color: var(--faint); font-size: 12.5px; font-style: italic; text-align: center; }

.tool {
  align-self: stretch; background: var(--surface); border: 1px solid var(--line);
  border-radius: 14px; overflow: hidden;
}
.tool > .head {
  display: flex; align-items: center; gap: 9px; padding: 10px 13px; width: 100%;
  text-align: left; font-size: 13.5px; min-width: 0;
}
.tool .tname { font-weight: 650; font-family: var(--mono); font-size: 12.5px; flex: none; }
.tool .targ { color: var(--dim); font-family: var(--mono); font-size: 12px; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; flex: 1; }
.tool .dot { width: 7px; height: 7px; border-radius: 50%; flex: none; background: var(--faint); }
.tool .dot.ok { background: var(--ok); }
.tool .dot.err { background: var(--err); }
.tool .dot.spin { background: var(--warn); animation: blink 1s ease-in-out infinite; }
@keyframes blink { 50% { opacity: .25; } }
.tool .chev { color: var(--faint); flex: none; font-size: 11px; transition: transform .18s; }
.tool.open .chev { transform: rotate(90deg); }
.tool .body { display: none; border-top: 1px solid var(--line); }
.tool.open .body { display: block; }
.tool .body pre {
  margin: 0; padding: 11px 13px; font-family: var(--mono); font-size: 12px;
  line-height: 1.55; overflow-x: auto; white-space: pre-wrap; overflow-wrap: break-word;
  max-height: 300px; overflow-y: auto; color: var(--dim);
}
.tool .body pre.err { color: var(--err); }
.tool .body .lbl { font-size: 10.5px; text-transform: uppercase; letter-spacing: .8px; color: var(--faint); padding: 9px 13px 0; }

.approval {
  align-self: stretch; background: var(--accent-soft); border: 1px solid rgba(255,115,101,.35);
  border-radius: 14px; padding: 13px 15px;
}
.approval .q { font-size: 13.5px; margin-bottom: 4px; }
.approval .q b { font-family: var(--mono); font-size: 12.5px; }
.approval pre {
  font-family: var(--mono); font-size: 12px; color: var(--dim); background: rgba(0,0,0,.25);
  border-radius: 10px; padding: 9px 11px; margin: 8px 0 11px; overflow-x: auto;
  white-space: pre-wrap; overflow-wrap: break-word; max-height: 180px; overflow-y: auto;
}
.approval .row { display: flex; gap: 8px; }
.abtn { flex: 1; padding: 9px 4px; border-radius: 11px; font-size: 13.5px; font-weight: 600; border: 1px solid var(--line2); }
.abtn:active { transform: scale(.97); }
.abtn.deny { color: var(--err); }
.abtn.once { background: var(--accent); color: #14100f; border-color: transparent; }
.abtn.always { color: var(--text); }
.approval.resolved { opacity: .55; }
.approval.resolved .row { display: none; }
.approval .verdict { font-size: 12.5px; font-weight: 600; }

.working { display: none; align-items: center; gap: 9px; color: var(--dim); font-size: 13.5px; padding: 2px 4px; align-self: flex-start; }
.working.on { display: flex; }
.working .d { width: 6px; height: 6px; border-radius: 50%; background: var(--accent); animation: bounce 1.2s infinite; }
.working .d:nth-child(2) { animation-delay: .15s; }
.working .d:nth-child(3) { animation-delay: .3s; }
@keyframes bounce { 30% { transform: translateY(-4px); opacity: .5; } }

/* ---------- composer ---------- */
.composer {
  flex: none; padding: 10px 12px calc(10px + var(--sab));
  background: rgba(11,15,20,.86); backdrop-filter: blur(18px); -webkit-backdrop-filter: blur(18px);
  border-top: 1px solid var(--line); display: flex; gap: 9px; align-items: flex-end;
}
.composer textarea {
  flex: 1; background: var(--surface2); border: 1px solid var(--line2); border-radius: 19px;
  padding: 10px 15px; resize: none; max-height: 132px; min-height: 42px; outline: none;
  line-height: 1.4; font-size: 16px;
}
.composer textarea:focus { border-color: rgba(255,115,101,.5); }
.sendbtn {
  width: 42px; height: 42px; border-radius: 50%; background: var(--accent); color: #14100f;
  display: grid; place-items: center; font-size: 18px; flex: none;
}
.sendbtn:disabled { background: var(--surface2); color: var(--faint); }
.sendbtn.stop { background: var(--err); color: #180c0c; }

/* ---------- sheets / modals ---------- */
.sheetwrap { position: fixed; inset: 0; z-index: 40; display: none; }
.sheetwrap.open { display: block; }
.sheetwrap .dimmer { position: absolute; inset: 0; background: rgba(0,0,0,.55); }
.sheet {
  position: absolute; left: 0; right: 0; bottom: 0; max-height: 88dvh;
  background: var(--surface); border-radius: 22px 22px 0 0; border: 1px solid var(--line2); border-bottom: 0;
  padding: 10px 18px calc(20px + var(--sab)); display: flex; flex-direction: column;
  animation: rise .22s ease-out;
}
@keyframes rise { from { transform: translateY(40px); opacity: .4; } }
.grab { width: 40px; height: 4.5px; border-radius: 3px; background: var(--line2); margin: 4px auto 12px; flex: none; }
.sheet h2 { font-size: 17px; margin: 0 0 14px; }
.sheet .lbl { font-size: 11.5px; text-transform: uppercase; letter-spacing: .8px; color: var(--faint); margin: 14px 0 7px; }
.seg { display: flex; background: var(--surface2); border: 1px solid var(--line); border-radius: 12px; padding: 3px; }
.seg button { flex: 1; padding: 8px 2px; border-radius: 9px; font-size: 12.5px; color: var(--dim); font-weight: 600; }
.seg button.on { background: var(--raise); color: var(--text); box-shadow: 0 1px 4px rgba(0,0,0,.4); }
.select, .field {
  width: 100%; background: var(--surface2); border: 1px solid var(--line2); border-radius: 12px;
  padding: 11px 14px; outline: none; appearance: none; -webkit-appearance: none; font-size: 15px;
}
.primary {
  width: 100%; background: var(--accent); color: #14100f; font-weight: 700; font-size: 16px;
  padding: 14px; border-radius: 14px; margin-top: 20px;
}
.primary:disabled { background: var(--surface2); color: var(--faint); }
.primary:active { transform: scale(.98); }

/* workspace browser */
.wsbar { display: flex; align-items: center; gap: 8px; margin-bottom: 8px; }
.wspath { font-family: var(--mono); font-size: 12px; color: var(--dim); overflow: hidden; text-overflow: ellipsis; white-space: nowrap; direction: rtl; text-align: left; flex: 1; }
.wslist { overflow-y: auto; max-height: 34dvh; border: 1px solid var(--line); border-radius: 12px; background: var(--bg); }
.wsrow { display: flex; align-items: center; gap: 10px; width: 100%; text-align: left; padding: 11px 14px; border-bottom: 1px solid var(--line); font-size: 14.5px; }
.wsrow:last-child { border-bottom: 0; }
.wsrow:active { background: var(--surface2); }
.wsrow .repo { margin-left: auto; font-size: 10.5px; color: var(--accent); border: 1px solid rgba(255,115,101,.4); padding: 1px 7px; border-radius: 99px; flex: none; }
.wsempty { padding: 18px; color: var(--faint); font-size: 13.5px; text-align: center; }

/* ---------- connect ---------- */
.connect { flex: 1; display: flex; flex-direction: column; justify-content: center; padding: 34px 28px calc(34px + var(--sab)); max-width: 430px; margin: 0 auto; width: 100%; }
.connect .logo { width: 76px; height: 76px; border-radius: 22px; margin: 0 auto 18px; display: block; }
.connect h1 { text-align: center; font-size: 25px; margin: 0 0 4px; }
.connect .sub { text-align: center; color: var(--dim); font-size: 14px; margin-bottom: 30px; }
.connect .lbl { font-size: 11.5px; text-transform: uppercase; letter-spacing: .8px; color: var(--faint); margin: 14px 0 7px; }
.cerr { color: var(--err); font-size: 13.5px; margin-top: 14px; text-align: center; min-height: 20px; }

/* toast */
#toast {
  position: fixed; left: 50%; transform: translateX(-50%); bottom: calc(90px + var(--sab));
  background: var(--raise); border: 1px solid var(--line2); color: var(--text);
  padding: 10px 18px; border-radius: 99px; font-size: 13.5px; z-index: 80;
  opacity: 0; transition: opacity .25s; pointer-events: none; max-width: 86vw;
  white-space: nowrap; overflow: hidden; text-overflow: ellipsis;
}
#toast.show { opacity: 1; }

/* ---------- desktop: two-pane ---------- */
#pane-list { position: relative; }
.nosession { display: none; flex: 1; place-items: center; color: var(--faint); }
@media (min-width: 920px) {
  #app.connected { flex-direction: row; }
  #app.connected #pane-list.active { width: 340px; flex: none; border-right: 1px solid var(--line); }
  #app.connected #nosession { display: grid; }
  #pane-session.active ~ #nosession { display: none; }
  #pane-session .hdr .back { display: none; }
  .msg.assistant, .tool, .approval { max-width: 780px; }
  .transcript { padding: 22px 26px; }
  .composer { padding: 12px 26px calc(12px + var(--sab)); }
  .composer textarea { max-width: 780px; }
  .sheet { left: 50%; right: auto; bottom: auto; top: 50%; transform: translate(-50%,-50%); width: 460px; border-radius: 22px; border-bottom: 1px solid var(--line2); animation: none; }
}
</style>
</head>
<body>
<div id="app">

  <!-- connect -->
  <div class="view" id="view-connect">
    <div class="connect">
      <img class="logo" src="/ui/icon.png" alt="">
      <h1>Krill</h1>
      <div class="sub">Remote agent on your own machine</div>
      <div class="lbl">Server</div>
      <input class="field" id="c-server" autocapitalize="off" autocorrect="off" placeholder="http://your-mac:57455">
      <div class="lbl">API key</div>
      <input class="field" id="c-key" type="password" autocapitalize="off" placeholder="KRILL_API_KEY (blank if none)">
      <button class="primary" id="c-go">Connect</button>
      <div class="cerr" id="c-err"></div>
    </div>
  </div>

  <!-- sessions list -->
  <div class="view" id="pane-list">
    <div class="hdr">
      <div class="orb" id="orb"></div>
      <h1>Krill</h1>
      <span class="chip" id="model-chip">connecting…</span>
      <div class="spacer"></div>
      <button class="iconbtn" id="btn-settings" aria-label="Settings">&#9881;&#65039;</button>
    </div>
    <div class="scroll" id="slist-scroll"><div class="slist" id="slist"></div></div>
    <button class="fab" id="btn-new" aria-label="New session">+</button>
  </div>

  <!-- session -->
  <div class="view" id="pane-session">
    <div class="hdr">
      <button class="iconbtn back" id="btn-back" aria-label="Back">&#8249;</button>
      <div style="min-width:0;flex:1">
        <div id="s-title" style="font-weight:650;font-size:15px;overflow:hidden;text-overflow:ellipsis;white-space:nowrap">Session</div>
        <div id="s-sub" style="font-size:11.5px;color:var(--dim);overflow:hidden;text-overflow:ellipsis;white-space:nowrap"></div>
      </div>
      <span class="pill idle" id="s-pill">idle</span>
      <button class="iconbtn" id="btn-more" aria-label="More">&#8943;</button>
    </div>
    <div class="scroll" id="t-scroll">
      <div class="transcript" id="transcript"></div>
      <div class="working" id="working" style="margin:0 18px 14px"><div class="d"></div><div class="d"></div><div class="d"></div><span id="working-label">Working…</span></div>
    </div>
    <div class="composer">
      <textarea id="input" rows="1" placeholder="Message the agent…" enterkeyhint="send"></textarea>
      <button class="sendbtn" id="btn-send" aria-label="Send">&#8593;</button>
    </div>
  </div>
  <div class="nosession" id="nosession"><div>Select or create a session</div></div>

</div>

<!-- new session sheet -->
<div class="sheetwrap" id="sheet-new">
  <div class="dimmer" data-close></div>
  <div class="sheet">
    <div class="grab"></div>
    <h2>New session</h2>
    <div class="lbl">Workspace</div>
    <div class="wsbar">
      <button class="iconbtn" id="ws-up" style="width:32px;height:32px" aria-label="Up">&#8249;</button>
      <div class="wspath" id="ws-path">~</div>
    </div>
    <div class="wslist" id="ws-list"></div>
    <div class="lbl">Model</div>
    <select class="select" id="new-model"></select>
    <div class="lbl">Permissions</div>
    <div class="seg" id="new-mode">
      <button data-v="plan">Plan</button>
      <button data-v="ask" class="on">Ask</button>
      <button data-v="accept-edits">Edits</button>
      <button data-v="accept-all">Auto</button>
    </div>
    <button class="primary" id="new-go">Start session</button>
  </div>
</div>

<!-- session actions sheet -->
<div class="sheetwrap" id="sheet-more">
  <div class="dimmer" data-close></div>
  <div class="sheet">
    <div class="grab"></div>
    <h2 id="more-title">Session</h2>
    <button class="abtn" id="more-cancel" style="margin-bottom:10px;padding:13px">Stop current run</button>
    <button class="abtn deny" id="more-delete" style="padding:13px">Delete session</button>
  </div>
</div>

<div id="toast"></div>

<script>
"use strict";
const $ = (id) => document.getElementById(id);
const store = {
  load() { try { return JSON.parse(localStorage.getItem("krill.ui")) || {}; } catch { return {}; } },
  save(v) { localStorage.setItem("krill.ui", JSON.stringify(v)); },
};
let cfg = store.load();          // {server, key}
let sessions = [];
let cur = null;                  // {id, meta, lastSeq, tools:Map, aborter, openApproval}
let listTimer = null;

/* ---------------- transport ---------------- */
function base() { return (cfg.server || location.origin).replace(/\/+$/, ""); }
function hdrs(json) {
  const h = {};
  if (cfg.key) h["Authorization"] = "Bearer " + cfg.key;
  if (json) h["Content-Type"] = "application/json";
  return h;
}
async function api(method, path, body) {
  const r = await fetch(base() + path, {
    method, headers: hdrs(body !== undefined),
    body: body !== undefined ? JSON.stringify(body) : undefined,
  });
  let data = null;
  try { data = await r.json(); } catch {}
  if (!r.ok) throw new Error((data && data.error) || (method + " " + path + " -> " + r.status));
  return data;
}

/* ---------------- tiny markdown ---------------- */
function esc(s) { return s.replace(/&/g, "&amp;").replace(/</g, "&lt;").replace(/>/g, "&gt;"); }
function inlineMd(s) {
  return s
    .replace(/`([^`]+)`/g, (_, c) => "<code>" + c + "</code>")
    .replace(/\*\*([^*]+)\*\*/g, "<b>$1</b>")
    .replace(/(^|\W)\*([^*\s][^*]*)\*/g, "$1<i>$2</i>")
    .replace(/\[([^\]]+)\]\((https?:[^)\s]+)\)/g, '<a href="$2" target="_blank" rel="noopener">$1</a>');
}
function md(src) {
  const lines = esc(src).split("\n");
  let out = "", i = 0, para = [];
  const flush = () => { if (para.length) { out += "<p>" + inlineMd(para.join("<br>")) + "</p>"; para = []; } };
  while (i < lines.length) {
    const l = lines[i];
    const fence = l.match(/^```(\w*)\s*$/);
    if (fence) {
      flush();
      const buf = [];
      i++;
      while (i < lines.length && !/^```\s*$/.test(lines[i])) { buf.push(lines[i]); i++; }
      i++;
      out += "<pre><code>" + buf.join("\n") + "</code></pre>";
      continue;
    }
    const h = l.match(/^(#{1,3})\s+(.*)$/);
    if (h) { flush(); out += "<h" + h[1].length + ">" + inlineMd(h[2]) + "</h" + h[1].length + ">"; i++; continue; }
    const li = l.match(/^\s*[-*]\s+(.*)$/);
    if (li) {
      flush();
      let items = "";
      while (i < lines.length) {
        const m = lines[i].match(/^\s*[-*]\s+(.*)$/);
        if (!m) break;
        items += "<li>" + inlineMd(m[1]) + "</li>"; i++;
      }
      out += "<ul>" + items + "</ul>";
      continue;
    }
    const ol = l.match(/^\s*\d+[.)]\s+(.*)$/);
    if (ol) {
      flush();
      let items = "";
      while (i < lines.length) {
        const m = lines[i].match(/^\s*\d+[.)]\s+(.*)$/);
        if (!m) break;
        items += "<li>" + inlineMd(m[1]) + "</li>"; i++;
      }
      out += "<ol>" + items + "</ol>";
      continue;
    }
    if (l.trim() === "") { flush(); } else { para.push(l); }
    i++;
  }
  flush();
  return out;
}

/* ---------------- view switching ---------------- */
const isDesktop = () => matchMedia("(min-width: 920px)").matches;
function show(view) {
  $("app").classList.toggle("connected", view !== "connect");
  for (const v of ["view-connect", "pane-list", "pane-session"]) $(v).classList.remove("active");
  if (view === "connect") { $("view-connect").classList.add("active"); return; }
  if (isDesktop()) {
    $("pane-list").classList.add("active");
    if (view === "session" && cur) $("pane-session").classList.add("active");
  } else {
    $(view === "session" ? "pane-session" : "pane-list").classList.add("active");
  }
}

/* ---------------- toast ---------------- */
let toastTimer = null;
function toast(msg) {
  const t = $("toast");
  t.textContent = msg; t.classList.add("show");
  clearTimeout(toastTimer);
  toastTimer = setTimeout(() => t.classList.remove("show"), 2600);
}

/* ---------------- status + sessions list ---------------- */
async function refreshStatus() {
  try {
    const s = await api("GET", "/v1/status");
    $("orb").className = "orb " + (s.model_loaded ? "ready" : "idle");
    $("model-chip").textContent = s.model || "no model loaded";
    return s;
  } catch (e) {
    $("orb").className = "orb down";
    $("model-chip").textContent = "unreachable";
    return null;
  }
}
function rel(iso) {
  const d = (Date.now() - new Date(iso).getTime()) / 1000;
  if (d < 60) return "just now";
  if (d < 3600) return Math.floor(d / 60) + "m ago";
  if (d < 86400) return Math.floor(d / 3600) + "h ago";
  return Math.floor(d / 86400) + "d ago";
}
function baseName(p) { const parts = p.split("/").filter(Boolean); return parts[parts.length - 1] || "/"; }
async function refreshSessions() {
  try {
    const r = await api("GET", "/v1/agent/sessions");
    sessions = r.sessions || [];
  } catch (e) { return; }
  const el = $("slist");
  if (!sessions.length) {
    el.innerHTML = '<div class="empty"><div class="big">&#129424;</div>' +
      "<div><b>No sessions yet</b></div><div style='font-size:13.5px;margin-top:6px'>" +
      "Tap + to point the agent at a folder and give it a task.</div></div>";
    return;
  }
  el.innerHTML = "";
  for (const s of sessions) {
    const b = document.createElement("button");
    b.className = "scard";
    b.innerHTML =
      '<div class="t"><span class="txt">' + esc(s.title || "New session") + "</span></div>" +
      '<div class="m"><span class="pill ' + s.status + '">' + s.status + "</span>" +
      "<span>" + esc(baseName(s.workspace)) + "</span><span>&#183;</span><span>" + rel(s.created_at) + "</span></div>";
    b.onclick = () => openSession(s.id);
    el.appendChild(b);
  }
}

/* ---------------- transcript rendering ---------------- */
function tScroll() { return $("t-scroll"); }
function nearBottom() { const s = tScroll(); return s.scrollHeight - s.scrollTop - s.clientHeight < 140; }
function toBottom() { const s = tScroll(); s.scrollTop = s.scrollHeight; }

function argSummary(name, argsJSON) {
  try {
    const a = JSON.parse(argsJSON);
    return a.command || a.file_path || a.path || a.pattern || a.url || a.query
      || Object.values(a).find((v) => typeof v === "string") || "";
  } catch { return argsJSON; }
}
function addUser(text) {
  const d = document.createElement("div");
  d.className = "msg user"; d.textContent = text;
  $("transcript").appendChild(d);
}
function addAssistant(text) {
  const d = document.createElement("div");
  d.className = "msg assistant";
  d.innerHTML = '<div class="md">' + md(text) + "</div>";
  $("transcript").appendChild(d);
}
function addNote(text) {
  const d = document.createElement("div");
  d.className = "note"; d.textContent = text;
  $("transcript").appendChild(d);
}
function addToolCall(name, args) {
  const d = document.createElement("div");
  d.className = "tool";
  const pretty = (() => { try { return JSON.stringify(JSON.parse(args), null, 2); } catch { return args; } })();
  d.innerHTML =
    '<button class="head"><span class="dot spin"></span><span class="tname">' + esc(name) + "</span>" +
    '<span class="targ">' + esc(argSummary(name, args)) + "</span>" +
    '<span class="chev">&#9654;</span></button>' +
    '<div class="body"><div class="lbl">Arguments</div><pre>' + esc(pretty) + "</pre>" +
    '<div class="result"></div></div>';
  d.querySelector(".head").onclick = () => d.classList.toggle("open");
  $("transcript").appendChild(d);
  cur.tools.set(name, d);   // latest open card per tool name
  return d;
}
function addToolResult(name, content, isError) {
  let card = cur.tools.get(name);
  if (!card || card.dataset.done) card = addToolCall(name, "{}");
  card.dataset.done = "1";
  cur.tools.delete(name);
  card.querySelector(".dot").className = "dot " + (isError ? "err" : "ok");
  const clip = content.length > 4000 ? content.slice(0, 4000) + "\n… (" + content.length + " chars)" : content;
  card.querySelector(".result").innerHTML =
    '<div class="lbl">Result</div><pre class="' + (isError ? "err" : "") + '">' + esc(clip) + "</pre>";
  if (isError) card.classList.add("open");
}
function addApproval(ev) {
  const d = document.createElement("div");
  d.className = "approval"; d.dataset.aid = ev.id;
  const pretty = (() => { try { return JSON.stringify(JSON.parse(ev.args), null, 2); } catch { return ev.args; } })();
  d.innerHTML =
    '<div class="q">Run <b>' + esc(ev.tool) + "</b>?</div><pre>" + esc(pretty) + "</pre>" +
    '<div class="row"><button class="abtn deny">Deny</button>' +
    '<button class="abtn once">Allow</button>' +
    '<button class="abtn always">Always</button></div>' +
    '<div class="verdict"></div>';
  const answer = async (allow, always) => {
    try { await api("POST", "/v1/agent/sessions/" + cur.id + "/approvals", { id: ev.id, allow, always }); }
    catch (e) { toast(e.message); }
  };
  d.querySelector(".deny").onclick = () => answer(false, false);
  d.querySelector(".once").onclick = () => answer(true, false);
  d.querySelector(".always").onclick = () => answer(true, true);
  $("transcript").appendChild(d);
  cur.openApproval = d;
}
function resolveApproval(ev) {
  const d = document.querySelector('.approval[data-aid="' + CSS.escape(ev.id) + '"]');
  if (!d) return;
  d.classList.add("resolved");
  d.querySelector(".verdict").textContent = ev.allow ? "Allowed" : "Denied";
  d.querySelector(".verdict").style.color = ev.allow ? "var(--ok)" : "var(--err)";
  if (cur && cur.openApproval === d) cur.openApproval = null;
}
function setSessionStatus(status) {
  if (!cur) return;
  cur.meta.status = status;
  $("s-pill").className = "pill " + status;
  $("s-pill").textContent = status;
  const running = status === "running" || status === "waiting";
  $("working").classList.toggle("on", running);
  $("working-label").textContent = status === "waiting" ? "Waiting for your approval…" : "Working…";
  $("btn-send").classList.toggle("stop", running);
  $("btn-send").innerHTML = running ? "&#9632;" : "&#8593;";
}
function applyEvent(ev) {
  switch (ev.type) {
    case "user": addUser(ev.text); break;
    case "assistant": case "assistant_final": addAssistant(ev.text); break;
    case "tool_call": addToolCall(ev.name, ev.args); break;
    case "tool_result": addToolResult(ev.name, ev.content, ev.is_error); break;
    case "note": addNote(ev.text); break;
    case "status": setSessionStatus(ev.status); break;
    case "approval_request": addApproval(ev); break;
    case "approval_resolved": resolveApproval(ev); break;
  }
}

/* ---------------- SSE tail ---------------- */
async function tail(sessionId) {
  while (cur && cur.id === sessionId) {
    const aborter = new AbortController();
    cur.aborter = aborter;
    try {
      const r = await fetch(base() + "/v1/agent/sessions/" + sessionId + "/events?since=" + cur.lastSeq,
        { headers: hdrs(false), signal: aborter.signal });
      if (!r.ok) throw new Error("events " + r.status);
      const reader = r.body.getReader();
      const dec = new TextDecoder();
      let buf = "";
      for (;;) {
        const { done, value } = await reader.read();
        if (done) break;
        buf += dec.decode(value, { stream: true });
        let idx;
        while ((idx = buf.indexOf("\n\n")) >= 0) {
          const chunk = buf.slice(0, idx); buf = buf.slice(idx + 2);
          let seq = null, data = null;
          for (const line of chunk.split("\n")) {
            if (line.startsWith("id: ")) seq = parseInt(line.slice(4), 10);
            else if (line.startsWith("data: ")) data = line.slice(6);
          }
          if (data == null) continue;   // heartbeat comment
          if (!cur || cur.id !== sessionId) return;
          if (seq != null) {
            if (seq <= cur.lastSeq) continue;   // duplicate on reconnect
            cur.lastSeq = seq;
          }
          try {
            const keep = nearBottom();
            applyEvent(JSON.parse(data));
            if (keep) toBottom();
          } catch {}
        }
      }
    } catch (e) {
      if (aborter.signal.aborted) return;
    }
    if (!cur || cur.id !== sessionId) return;
    await new Promise((res) => setTimeout(res, 1500));   // reconnect backoff
  }
}

/* ---------------- session open/close ---------------- */
async function openSession(id) {
  closeSession();
  let detail;
  try { detail = await api("GET", "/v1/agent/sessions/" + id); }
  catch (e) { toast(e.message); return; }
  cur = { id, meta: detail, lastSeq: 0, tools: new Map(), aborter: null, openApproval: null };
  $("transcript").innerHTML = "";
  $("s-title").textContent = detail.title || "New session";
  $("s-sub").textContent = baseName(detail.workspace) + " · " + detail.permission_mode
    + (detail.model ? " · " + detail.model : "");
  for (const ev of detail.events || []) {
    if (typeof ev.seq === "number") cur.lastSeq = Math.max(cur.lastSeq, ev.seq);
    applyEvent(ev);
  }
  setSessionStatus(detail.status);
  show("session");
  toBottom();
  history.pushState({ s: id }, "", "#/s/" + id);
  tail(id);
}
function closeSession() {
  if (cur && cur.aborter) cur.aborter.abort();
  cur = null;
}
function backToList() {
  closeSession();
  show("list");
  refreshSessions();
}

/* ---------------- composer ---------------- */
const input = $("input");
input.addEventListener("input", () => {
  input.style.height = "auto";
  input.style.height = Math.min(input.scrollHeight, 132) + "px";
});
input.addEventListener("keydown", (e) => {
  if (e.key === "Enter" && !e.shiftKey && isDesktop()) { e.preventDefault(); $("btn-send").click(); }
});
$("btn-send").onclick = async () => {
  if (!cur) return;
  const running = cur.meta.status === "running" || cur.meta.status === "waiting";
  if (running) {
    try { await api("POST", "/v1/agent/sessions/" + cur.id + "/cancel"); } catch (e) { toast(e.message); }
    return;
  }
  const text = input.value.trim();
  if (!text) return;
  input.value = ""; input.style.height = "auto";
  try { await api("POST", "/v1/agent/sessions/" + cur.id + "/messages", { text }); }
  catch (e) { toast(e.message); }
  toBottom();
};

/* ---------------- new session sheet ---------------- */
let ws = { path: "~", chosen: null };
async function loadWs(path) {
  let r;
  try { r = await api("GET", "/v1/agent/workspaces?path=" + encodeURIComponent(path)); }
  catch (e) { toast(e.message); return; }
  ws.path = r.path; ws.parent = r.parent; ws.chosen = r.path;
  $("ws-path").textContent = r.path;
  const list = $("ws-list");
  list.innerHTML = "";
  if (!r.dirs.length) list.innerHTML = '<div class="wsempty">No folders here — using this directory.</div>';
  for (const d of r.dirs) {
    const b = document.createElement("button");
    b.className = "wsrow";
    b.innerHTML = "&#128193; <span>" + esc(d.name) + "</span>" + (d.is_repo ? '<span class="repo">git</span>' : "");
    b.onclick = () => loadWs(d.path);
    list.appendChild(b);
  }
}
$("ws-up").onclick = () => { if (ws.parent) loadWs(ws.parent); };
$("new-mode").addEventListener("click", (e) => {
  const b = e.target.closest("button"); if (!b) return;
  for (const x of $("new-mode").children) x.classList.remove("on");
  b.classList.add("on");
});
async function openNewSheet() {
  $("sheet-new").classList.add("open");
  loadWs(ws.path || "~");
  const sel = $("new-model");
  sel.innerHTML = '<option value="">Active model (server default)</option>';
  try {
    const s = await api("GET", "/v1/status");
    for (const m of s.installed_models || []) {
      const o = document.createElement("option");
      o.value = m; o.textContent = m + (s.model === m ? "  (loaded)" : "");
      if (s.model === m) o.selected = true;
      sel.appendChild(o);
    }
  } catch {}
}
$("new-go").onclick = async () => {
  const mode = $("new-mode").querySelector(".on").dataset.v;
  const body = { workspace: ws.chosen, permission_mode: mode };
  const model = $("new-model").value;
  if (model) body.model = model;
  let s;
  try { s = await api("POST", "/v1/agent/sessions", body); }
  catch (e) { toast(e.message); return; }
  $("sheet-new").classList.remove("open");
  await openSession(s.id);
  input.focus();
};

/* ---------------- more sheet ---------------- */
$("btn-more").onclick = () => { if (cur) { $("more-title").textContent = cur.meta.title || "Session"; $("sheet-more").classList.add("open"); } };
$("more-cancel").onclick = async () => {
  $("sheet-more").classList.remove("open");
  if (!cur) return;
  try { await api("POST", "/v1/agent/sessions/" + cur.id + "/cancel"); toast("Stopping…"); }
  catch (e) { toast(e.message); }
};
$("more-delete").onclick = async () => {
  $("sheet-more").classList.remove("open");
  if (!cur) return;
  if (!confirm("Delete this session?")) return;
  try { await api("DELETE", "/v1/agent/sessions/" + cur.id); } catch (e) { toast(e.message); }
  backToList();
};

/* ---------------- wiring ---------------- */
for (const w of document.querySelectorAll(".sheetwrap")) {
  w.addEventListener("click", (e) => { if (e.target.dataset.close !== undefined) w.classList.remove("open"); });
}
$("btn-new").onclick = openNewSheet;
$("btn-back").onclick = () => { history.back(); };
$("btn-settings").onclick = () => { show("connect"); prefillConnect(); };
window.addEventListener("popstate", () => { if (cur) backToList(); });

function prefillConnect() {
  $("c-server").value = cfg.server || location.origin;
  $("c-key").value = cfg.key || "";
  $("c-err").textContent = "";
}
$("c-go").onclick = async () => {
  const server = $("c-server").value.trim().replace(/\/+$/, "") || location.origin;
  const key = $("c-key").value.trim();
  const probe = { server, key };
  const old = cfg; cfg = probe;
  try {
    await api("GET", "/v1/status");
  } catch (e) {
    cfg = old;
    $("c-err").textContent = "Could not connect: " + e.message;
    return;
  }
  store.save(cfg);
  boot();
};

async function boot() {
  prefillConnect();
  const s = await refreshStatus();
  if (s === null && !cfg.server && !cfg.key) { show("connect"); return; }
  if (s === null) { show("connect"); $("c-err").textContent = "Saved server is unreachable."; return; }
  show("list");
  refreshSessions();
  clearInterval(listTimer);
  listTimer = setInterval(() => {
    refreshStatus();
    if (!cur || isDesktop()) refreshSessions();
  }, 8000);
}
document.addEventListener("visibilitychange", () => {
  if (document.visibilityState === "visible" && cur) {
    // resume the tail fast after the phone unlocks
    if (cur.aborter) cur.aborter.abort();
    const id = cur.id;
    setTimeout(() => { if (cur && cur.id === id) tail(id); }, 50);
  }
});
boot();
</script>
</body>
</html>
"""#
}
